SET search_path = maker3d, pg_catalog;
CREATE TABLE IF NOT EXISTS billing_contracts(id TEXT PRIMARY KEY,family_id INTEGER NOT NULL REFERENCES families(id),project_id INTEGER REFERENCES projects(id),purpose TEXT NOT NULL CHECK(purpose IN ('membership','project')),plan TEXT NOT NULL CHECK(plan IN ('monthly','annual')),provider TEXT NOT NULL CHECK(provider IN ('asaas','manual')),environment TEXT NOT NULL,method TEXT NOT NULL,installments INTEGER NOT NULL DEFAULT 1,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),status TEXT NOT NULL CHECK(status IN ('creating','pending','active','past_due','cancelled','needs_review','refunded')),gateway_subscription_id TEXT,gateway_charge_id TEXT,gateway_installment_id TEXT,checkout_url TEXT,current_period_end TEXT,request_key TEXT NOT NULL UNIQUE,created_by INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL,updated TEXT NOT NULL,error_note TEXT);
CREATE INDEX IF NOT EXISTS maker_billing_family ON billing_contracts(family_id,created);
CREATE UNIQUE INDEX IF NOT EXISTS maker_billing_recurring ON billing_contracts(family_id) WHERE provider='asaas' AND purpose='membership' AND method IN ('pix_recurring','card_recurring') AND status IN ('creating','pending','active','past_due','needs_review');
CREATE UNIQUE INDEX IF NOT EXISTS maker_billing_pending ON billing_contracts(family_id) WHERE purpose='membership' AND status IN ('creating','pending','needs_review');
CREATE UNIQUE INDEX IF NOT EXISTS maker_billing_project ON billing_contracts(project_id) WHERE project_id IS NOT NULL AND status IN ('creating','pending','needs_review');
CREATE TABLE IF NOT EXISTS billing_receipts(gateway TEXT NOT NULL,gateway_charge_id TEXT NOT NULL,contract_id TEXT NOT NULL REFERENCES billing_contracts(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),status TEXT NOT NULL CHECK(status IN ('paid','refunded')),payment_id INTEGER REFERENCES payments(id),entry_id INTEGER REFERENCES cash_entries(id),entitlement_end TEXT,created TEXT NOT NULL,updated TEXT NOT NULL,PRIMARY KEY(gateway,gateway_charge_id));
CREATE UNIQUE INDEX IF NOT EXISTS maker_billing_receipt_entry ON billing_receipts(entry_id) WHERE entry_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS maker_billing_receipt_payment ON billing_receipts(payment_id) WHERE payment_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS maker_billing_receipts_contract ON billing_receipts(contract_id,status);
ALTER TABLE billing_contracts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS maker3d_backend ON billing_contracts;
CREATE POLICY maker3d_backend ON billing_contracts TO maker3d_app USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON billing_contracts TO maker3d_app;
REVOKE ALL ON billing_contracts FROM PUBLIC, anon, authenticated;
ALTER TABLE billing_receipts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS maker3d_backend ON billing_receipts;
CREATE POLICY maker3d_backend ON billing_receipts TO maker3d_app USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE, DELETE ON billing_receipts TO maker3d_app;
REVOKE ALL ON billing_receipts FROM PUBLIC, anon, authenticated;
RESET search_path;
